<?php
require 'config.php'; require_role('student'); $title='Academic Records'; $u=$_SESSION['user']; $term=selected_term($pdo); $termId=$term?(int)$term['id']:0; $current=current_term($pdo); $isCurrent=$current&&$term&&(int)$current['id']===$termId;
if($isCurrent){$q=$pdo->prepare("SELECT s.id AS subject_id,s.code,s.name,s.units,e.status,'In Progress' AS grade,'Current Enrollment' AS remarks,COALESCE(f.name,'Assigned Faculty') teacher FROM enrollments e JOIN subjects s ON s.id=e.subject_id LEFT JOIN subject_offerings o ON o.id=e.offering_id LEFT JOIN users f ON f.id=o.faculty_id WHERE e.student_id=? AND e.term_id=? ORDER BY s.code");$q->execute([$u['id'],$termId]);$rows=$q->fetchAll();}else{$q=$pdo->prepare("SELECT s.id AS subject_id,s.code,s.name,s.units,r.grade,r.remarks,r.teacher FROM academic_records r JOIN subjects s ON s.id=r.subject_id WHERE r.user_id=? AND r.term_id=? ORDER BY s.code");$q->execute([$u['id'],$termId]);$rows=$q->fetchAll();}
$units=array_sum(array_map(fn($r)=>(int)$r['units'],$rows));$passed=0;foreach($rows as $r)if(strtolower((string)$r['remarks'])==='passed')$passed++;
require 'header.php';?>
<div class="section"><div class="section-intro"><div><span class="eyebrow">ACADEMIC RECORDS</span><h2><?=e($term['label']??'Academic Term')?></h2><p class="muted">View your subjects, units, teachers, and academic status for the selected term.</p></div><div class="button-group"><a class="btn" href="download_records.php?term=<?=e($term['term_key']??'')?>">Download Records</a><a class="btn" href="enrollment.php">Go to Enrollment</a></div></div><div class="enrollment-overview"><div><span>Subjects</span><strong><?=e(count($rows))?></strong></div><div><span>Total Units</span><strong><?=e($units)?></strong></div><div><span>Passed</span><strong><?=e($passed)?></strong></div><div><span>Term</span><strong><?=e($isCurrent?'Current':'Previous')?></strong></div></div><?php if(!$rows):?><p class="muted">No academic records are available for this term.</p><?php else:?><div class="table-scroll"><table class="table"><tr><th>Subject</th><th>Units</th><th>Teacher</th><th>Grade</th><th>Status</th></tr><?php foreach($rows as $r):?><tr><td><a href="subject_details.php?id=<?=e($r['subject_id'])?>"><b><?=e($r['code'])?></b></a><br><small><?=e($r['name'])?></small></td><td><?=e($r['units'])?></td><td><?=e($r['teacher']?:'Assigned Faculty')?></td><td><b><?=e($r['grade'])?></b></td><td><span class="badge <?=strtolower($r['remarks'])==='passed'?'approved':'pending'?>"><?=e($r['remarks'])?></span></td></tr><?php endforeach;?></table></div><?php endif;?></div>
<div class="admin-help"><span>Have a problem?</span><a href="contact.php">Contact Administration</a></div><?php require 'footer.php';?>
